function renderKpis(){let d=OVERVIEW?.delivery||{},td=targetFor('delivery'),md=managementSetting('delivery'),mw=managementSetting('warehouse'),rq=receivingQty(),df=baselineFallback('delivery'),ex=currentExposure();
let whRate=ex?.rate_per_10000!=null?Number(ex.rate_per_10000):null,whScore=ex?.score!=null?Number(ex.score):null,whStatus=!cutoffSummary().complete?'CUT_OFF_REQUIRED':(ex?.status||'DATA_REQUIRED');
let dLabel=df.isBaseline?'Baseline Jan–Jun 2026 · actual periode belum tersedia':(d.delivered?fmt(d.delivered)+' Delivered':'denominator belum tersedia');
let whFoot=whStatus==='PROVISIONAL'?`SAP movement s.d. ${esc(ex.data_through_date||'—')} · Exposure MTD ${fmt(ex.exposure)} Box`:whStatus==='FINAL'?`Final month-end · Exposure ${fmt(ex.exposure)} Box`:whStatus==='REVIEW_REQUIRED'?`${fmt(ex.review_rows)} movement row perlu mapping sebelum KPI dihitung`:whStatus==='CUT_OFF_REQUIRED'?`Cut-off stock siap ${cutoffSummary().ready}/${cutoffSummary().total}`:'Menunggu upload SAP MB51 D+1 / MTD';
$('kpis').innerHTML=`
<div class="card kpi"><div class="label">▣ Delivery Breakage Rate</div><div class="sub">Pecah Kiriman / 10.000 Delivered</div><div class="value">${rate(df.value)} ${df.value!=null?'<span class="unit">/10.000</span>':''}</div><div class="foot">${df.isBaseline?'<b class="warn">BASELINE PRESENTATION</b> · ':''}Target Utama ${md?.target_rate_per_10000!=null?'≤ '+fmt(md.target_rate_per_10000):'DATA REQUIRED'} · Recovery ${td?'≤ '+fmt(td.target_value):'—'} · ${dLabel}</div>${pillFor(df.value,'delivery')}</div>
<div class="card kpi"><div class="label">⌂ Warehouse Breakage Rate</div><div class="sub">Pecah Gudang / (Stock Awal + Stock In + Stock Out)</div><div class="value">${whRate==null?(whStatus==='CUT_OFF_REQUIRED'?'CUT-OFF REQUIRED':whStatus==='REVIEW_REQUIRED'?'REVIEW REQUIRED':'DATA REQUIRED'):rate(whRate)+' <span class="unit">/10.000</span>'}</div><div class="foot"><b>Target ≤ ${mw?.target_pct!=null?pct4(mw.target_pct)+'%':'—'} (${mw?.target_rate_per_10000!=null?fmt(mw.target_rate_per_10000)+' /10.000':'—'})</b><br>${whFoot}</div>${kpiStatusPill(whStatus)}</div>
<div class="card kpi"><div class="label">◇ Receiving Breakage</div><div class="sub">Qty / Control Volume</div><div class="value">${fmt(rq)} <span class="unit">BOX</span></div><div class="foot">Receiving belum mempunyai denominator authoritative dan tidak masuk rate KPI.</div><span class="status-pill s-blue">Qty only</span></div>
<div class="card kpi"><div class="label">✺ Score KPI Warehouse ${SCOPE==='ALL'?'Nasional':esc(SCOPE)}</div><div class="sub">Target Utama Management</div><div class="value ${whScore==null?'datareq':''}">${whScore==null?(whStatus==='CUT_OFF_REQUIRED'?'CUT-OFF REQUIRED':whStatus==='REVIEW_REQUIRED'?'REVIEW REQUIRED':'DATA REQUIRED'):scoreText(whScore)}</div><div class="foot">Formula: min(100, Target ÷ Actual × 100). ${whStatus==='PROVISIONAL'?'Score sementara D+1/MTD dan dapat berubah setelah upload berikutnya.':whStatus==='FINAL'?'Score final setelah month-end closing.':whFoot}</div></div>
<div class="card kpi"><div class="label">◎ Target Utama KPI</div><div class="sub">Management Setting</div><div class="value">${mw?.target_pct!=null?pct4(mw.target_pct)+'%':'—'}</div><div class="foot">Warehouse · ${mw?esc(mw.denominator_label):'DATA REQUIRED'}<br>Delivery: ${md?.target_rate_per_10000!=null?'≤ '+fmt(md.target_rate_per_10000)+' /10.000':'—'}</div><span class="status-pill s-blue">${KPI_SETTINGS.length?'Aktif':'DATA REQUIRED'}</span></div>`}
function renderTargetWindow(){let all=TARGETS.filter(x=>x.program_code==='BREAKAGE_REDUCTION_SEP_OCT_2026');const windows=[...new Map(all.map(x=>[x.window_code,x])).values()].sort((a,b)=>a.window_order-b.window_order);const val=(k,w)=>all.find(x=>x.kpi_code===k&&x.window_code===w)?.target_value;$('targetWindow').innerHTML=`<div class="section-title">▣ Target Window KPI Rate / 10.000 <span style="font-size:10px;color:var(--muted);font-weight:600">Target resmi Project Breakage All RDC</span></div><div class="target-matrix" style="grid-template-columns:minmax(155px,1.35fr) repeat(${Math.max(windows.length,1)},minmax(115px,1fr))"><div class="tm-cell tm-head">KPI</div>${windows.map(w=>`<div class="tm-cell tm-head">${esc(w.window_label)}</div>`).join('')}<div class="tm-cell tm-kpi">Delivery Breakage Rate</div>${windows.map(w=>`<div class="tm-cell" style="text-align:center;font-weight:800">≤ ${fmt(val('delivery',w.window_code))}</div>`).join('')}<div class="tm-cell tm-kpi">Warehouse Breakage Rate</div>${windows.map(w=>`<div class="tm-cell" style="text-align:center;font-weight:800">≤ ${fmt(val('warehouse',w.window_code))}</div>`).join('')}</div><div class="smallnote" style="margin-top:8px">Receiving tetap Qty/control volume. National Rate = SUM numerator / SUM denominator, bukan average rate RDC.</div>`}
function renderBaselinePanel(){let b25=BASELINE25,b26=BASELINE26,n25=b25?.national,n26=b26?.national;if(!n25||!n26){$('baselinePanel').innerHTML='<div class="empty">Baseline presentasi belum tersedia.</div>';return}let rows26=b26.rows||[],rows25=b25.rows||[],get25=rdc=>rows25.find(x=>x.rdc===rdc)||{};let tableRows=(SCOPE==='ALL'?rows26:rows26.filter(x=>x.rdc===SCOPE)).map(r=>{let p=get25(r.rdc),dr=baselineDeliveryRate(r);return `<tr><td>${esc(r.rdc)}</td><td>${fmt(p.delivered_box)}</td><td>${fmt(r.delivered_box)}</td><td>${pctGrowth(p.delivered_box,r.delivered_box)}</td><td>${fmt(p.breakage_total_box)}</td><td>${fmt(r.breakage_total_box)}</td><td>${pctGrowth(p.breakage_total_box,r.breakage_total_box)}</td><td>${fmt(r.delivery_breakage_box)}</td><td>${dr==null?'—':rate(dr)}</td><td>${fmt(r.warehouse_breakage_box)}</td><td class="warn">DATA REQUIRED</td></tr>`}).join('');$('baselinePanel').innerHTML=`<div class="section-title">Baseline Awal — Data Presentasi Breakage <span class="status-pill s-blue" style="margin-left:auto">Jan–Jun 2025 vs Jan–Jun 2026</span></div><div class="hl-strip" style="margin:0 0 12px"><div class="hl-item"><div><div class="smallnote">Delivery Rate ${SCOPE==='ALL'?'Nasional':esc(SCOPE)}</div><b>${rate(n25.delivery_rate)} → ${rate(n26.delivery_rate)}</b><div class="bad">${pctGrowth(exactDeliveryRate(n25),exactDeliveryRate(n26))}</div></div></div><div class="hl-item"><div><div class="smallnote">Warehouse Rate ${SCOPE==='ALL'?'Nasional':esc(SCOPE)}</div><b>${rate(n25.warehouse_rate)} → ${rate(n26.warehouse_rate)}</b><div class="bad">${pctGrowth(exactWarehouseRate(n25),exactWarehouseRate(n26))}</div></div></div><div class="hl-item"><div><div class="smallnote">Total Breakage</div><b>${fmt(n25.breakage_total_box)} → ${fmt(n26.breakage_total_box)} Box</b><div class="bad">${pctGrowth(n25.breakage_total_box,n26.breakage_total_box)}</div></div></div><div class="hl-item"><div><div class="smallnote">Service / Delivered</div><b>${fmt(n25.delivered_box)} → ${fmt(n26.delivered_box)} Box</b><div>${pctGrowth(n25.delivered_box,n26.delivered_box)}</div></div></div></div><div class="tablewrap"><table class="tbl"><thead><tr><th>RDC</th><th>Service 2025</th><th>Service 2026</th><th>Growth</th><th>Total Pecah 2025</th><th>Total Pecah 2026</th><th>Growth</th><th>Pecah Kirim 2026</th><th>Delivery Rate*</th><th>Pecah WH 2026</th><th>WH Rate</th></tr></thead><tbody>${tableRows}</tbody></table></div><div class="smallnote" style="margin-top:9px"><b>Sumber:</b> Project Breakage All RDC — Management Review, 26 Aug 2026. *Delivery Rate per RDC dihitung dari Pecah Kiriman ÷ Service/Delivered × 10.000. Warehouse Rate per RDC tetap DATA REQUIRED karena presentasi tidak menyediakan Stock Exposure per RDC. Baseline ini tidak menggantikan Actual Operational Sep–Okt.</div>`}
function renderScorecard(){if(GRAN==='monthly')return renderMonthlyScorecard();return renderOperationalScorecard()}
function renderMonthlyScorecard(){let exRows=EXPOSURE?.rows||[];let exMap=Object.fromEntries(exRows.map(x=>[x.rdc,x]));let rows=RDCROWS.map(r=>{let td=targetFor('delivery'),wx=exMap[r.rdc]||{},dg=r.d_rate==null||!td?null:Number(r.d_rate)-Number(td.target_value);return {...r,d_target:td?.target_value,d_gap:dg,w_rate:wx.rate_per_10000,w_target:managementSetting('warehouse')?.target_rate_per_10000,w_gap:wx.rate_per_10000==null?null:Number(wx.rate_per_10000)-Number(managementSetting('warehouse')?.target_rate_per_10000||0),score:wx.score,kpi_status:wx.status}});let nx=currentExposure()||{},national={rdc:'NASIONAL',d_rate:OVERVIEW?.delivery?.rate,d_target:targetFor('delivery')?.target_value,d_gap:targetGap(OVERVIEW?.delivery?.rate,'delivery'),w_rate:nx.rate_per_10000,w_target:managementSetting('warehouse')?.target_rate_per_10000,w_gap:nx.rate_per_10000==null?null:Number(nx.rate_per_10000)-Number(managementSetting('warehouse')?.target_rate_per_10000||0),score:nx.score,kpi_status:nx.status};$('scorecard').innerHTML=`<div class="section-title" style="padding:12px 14px;margin:0">Rekap & Trend — Score per RDC</div><div class="subtabs"><button class="active">Rekap Bulanan</button><button>Score RDC</button><button>Score Nasional</button></div><div class="tablewrap"><table class="tbl"><thead><tr><th>RDC</th><th>Delivery Actual</th><th>Target</th><th>Gap</th><th>Warehouse Actual</th><th>Target</th><th>Gap</th><th>Score WH</th><th>Status WH</th></tr></thead><tbody>${[...rows,national].map(r=>`<tr class="${r.rdc==='NASIONAL'?'national':''}"><td>${esc(r.rdc)}</td><td>${rate(r.d_rate)}</td><td>${r.d_target!=null?'≤ '+fmt(r.d_target):'—'}</td><td class="${r.d_gap>0?'bad':'good'}">${r.d_gap==null?'—':(r.d_gap>0?'+':'')+fmt(r.d_gap)}</td><td>${rate(r.w_rate)}</td><td>${r.w_target!=null?'≤ '+fmt(r.w_target):'—'}</td><td class="${r.w_gap>0?'bad':'good'}">${r.w_gap==null?'—':(r.w_gap>0?'+':'')+fmt(r.w_gap)}</td><td>${r.score==null?'—':scoreText(r.score)}</td><td>${kpiStatusPill(r.kpi_status||'DATA_REQUIRED')}</td></tr>`).join('')}</tbody></table></div>`}
function groupIncidents(gran){let groups={};INCIDENTS.forEach(i=>{let d=new Date(i.occurrence_date+'T00:00:00');let key;if(gran==='daily')key=i.occurrence_date;else{let day=d.getDate();let wk=Math.ceil(day/7);key=`Week ${wk}`;}let g=groups[key]||(groups[key]={key,delivery:0,warehouse:0,receiving:0,cases:0});g[i.incident_type]=(g[i.incident_type]||0)+Number(i.qty_box||0);g.cases++});return Object.values(groups)}
function renderOperationalScorecard(){let rows=groupIncidents(GRAN);$('scorecard').innerHTML=`<div class="section-title" style="padding:12px 14px;margin:0">Rekap ${GRAN==='daily'?'Harian':'Mingguan'} — ${esc(SCOPE==='ALL'?'Nasional':SCOPE)}</div><div class="hint" style="margin:0 12px 10px">Incident quantity dapat direkap ${GRAN==='daily'?'per hari':'per minggu'}. Rate dan Score menunggu denominator harian/mingguan authoritative. Formula score sudah aktif.</div><div class="tablewrap"><table class="tbl"><thead><tr><th>Periode</th><th>Delivery Qty</th><th>Warehouse Qty</th><th>Receiving Qty</th><th>Kasus</th><th>Delivery Rate</th><th>Warehouse Rate</th><th>Score</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${esc(r.key)}</td><td>${fmt(r.delivery)}</td><td>${fmt(r.warehouse)}</td><td>${fmt(r.receiving)}</td><td>${r.cases}</td><td class="warn">DATA REQUIRED</td><td class="warn">DATA REQUIRED</td><td class="warn">DATA REQUIRED</td></tr>`).join(''):`<tr><td colspan="8"><div class="empty">Belum ada incident untuk periode ini.</div></td></tr>`}</tbody></table></div>`}
